import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Codex Security","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/codex-security.md","filePath":"zh/products/ai-coding/codex/codex-security.md","lastUpdated":1787042982000}'),s={name:"zh/products/ai-coding/codex/codex-security.md"};function c(d,t,n,i,l,h){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="codex-security" tabindex="-1">Codex Security <a class="header-anchor" href="#codex-security" aria-label="Permalink to &quot;Codex Security&quot;">​</a></h1><blockquote><p>这是一份<strong>教程</strong>——在你有权评估的仓库上跑一次只读扫描，然后读报告。Codex Security 是应用安全 Agent，<strong>三扇门</strong>：桌面插件、CLI/SDK、Cloud。本页是地图和第一次扫描，不抄官方每一条工作流。</p><p>官方落地页：<a href="https://learn.chatgpt.com/codex/security" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/security</a>。文档：<a href="https://learn.chatgpt.com/docs/security" target="_blank" rel="noreferrer">Codex Security</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需要</th><th>要求</th></tr></thead><tbody><tr><td>权限</td><td><strong>只</strong>扫你拥有或已获授权评估的代码</td></tr><tr><td>账号</td><td>具备 Codex Security 访问。效果最好：<a href="https://chatgpt.com/cyber" target="_blank" rel="noreferrer">Trusted Access for Cyber</a></td></tr><tr><td>桌面插件</td><td>带 Codex 的 <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT 桌面应用</a></td></tr><tr><td>CLI / SDK</td><td>能跑 <code>npx</code>；可选 TypeScript 应用</td></tr><tr><td>Cloud</td><td>仓库已在 <a href="./codex-cloud.html">Codex Cloud</a> 里可见</td></tr></tbody></table><p><strong>学习目标</strong>：分清三扇门；装好插件或跑通 CLI help；完成一次只读首扫；知道 Cloud Security 是研究预览。</p><p><strong>非目标</strong>：写 exploit / PoC；完整 SARIF/CI 手册（看官方 CI 文档）；Agent 沙箱理论（<a href="./codex-cli.html">CLI</a>）。</p><h2 id="三扇门-同一套扫描器" tabindex="-1">三扇门，同一套扫描器 <a class="header-anchor" href="#三扇门-同一套扫描器" aria-label="Permalink to &quot;三扇门，同一套扫描器&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Codex Security</span></span>
<span class="line"><span>├── Plugin          桌面工作台 + CLI \`/plugins\`</span></span>
<span class="line"><span>│                   Scans · Findings · Repositories</span></span>
<span class="line"><span>├── CLI / SDK       @openai/codex-security</span></span>
<span class="line"><span>│                   本机、批量、CI、TypeScript</span></span>
<span class="line"><span>└── Cloud           研究预览</span></span>
<span class="line"><span>                    经 Codex Cloud 扫已连接的 GitHub 仓库</span></span></code></pre></div><p>桌面 <strong>Security</strong> 工作台和 Codex CLI 都走 <strong>Codex Security 插件</strong>。Cloud 经 Codex Cloud 扫 GitHub。沙箱、审批、管理员策略仍是 <a href="https://learn.chatgpt.com/docs/agent-approvals-security" target="_blank" rel="noreferrer">agent security</a>——Security 不替代它们。</p><table tabindex="0"><thead><tr><th>门</th><th>何时用</th><th>从哪开始</th></tr></thead><tbody><tr><td>插件</td><td>桌面里交互分诊</td><td><a href="https://learn.chatgpt.com/docs/security/plugin" target="_blank" rel="noreferrer">Plugin quickstart</a></td></tr><tr><td>CLI / SDK</td><td>可重复本机扫描、批量清单、CI</td><td><a href="https://learn.chatgpt.com/docs/security/cli" target="_blank" rel="noreferrer">CLI quickstart</a> · <a href="https://learn.chatgpt.com/docs/security/sdk" target="_blank" rel="noreferrer">SDK</a></td></tr><tr><td>Cloud</td><td>托管扫已连接的 GitHub 仓库</td><td><a href="https://learn.chatgpt.com/docs/security/setup" target="_blank" rel="noreferrer">Cloud setup</a></td></tr></tbody></table><p>从 ChatGPT 装插件：<a href="https://chatgpt.com/plugins/share/676aca3811d54fa7bcdef5255236b3c4" target="_blank" rel="noreferrer">分享链接</a>。</p><h2 id="第一次本机扫描-插件" tabindex="-1">第一次本机扫描（插件） <a class="header-anchor" href="#第一次本机扫描-插件" aria-label="Permalink to &quot;第一次本机扫描（插件）&quot;">​</a></h2><p>官方首扫路径：<a href="https://learn.chatgpt.com/docs/security/plugin" target="_blank" rel="noreferrer">Plugin quickstart</a>。质量默认：<code>gpt-5.6-sol</code> + <code>xhigh</code> 推理。</p><h3 id="桌面" tabindex="-1">桌面 <a class="header-anchor" href="#桌面" aria-label="Permalink to &quot;桌面&quot;">​</a></h3><ol><li>在 ChatGPT 桌面应用里打开 Codex。</li><li><strong>Plugins</strong> → 搜 <strong>Codex Security</strong> → 安装并启用。</li><li>侧栏打开 <strong>Security</strong>。没有就升级应用和插件。</li><li><strong>Scans → + Scan</strong>。选仓库或文件夹。第一次先关 <strong>Deep scan</strong>。</li><li>开始扫描。审 <strong>Findings</strong>、覆盖率和 <code>report.md</code>。</li></ol><p>工作台：<strong>Scans</strong>（进度和历史）、<strong>Findings</strong>（问题和证据）、<strong>Repositories</strong>（仓库历史）。细节：<a href="https://learn.chatgpt.com/docs/security/plugin/workbench" target="_blank" rel="noreferrer">Security workbench</a>。</p><h3 id="经插件的-cli-会话" tabindex="-1">经插件的 CLI 会话 <a class="header-anchor" href="#经插件的-cli-会话" aria-label="Permalink to &quot;经插件的 CLI 会话&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/code/your-repo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span></span></code></pre></div><p>然后 <code>/plugins</code> → 安装 <strong>Codex Security</strong> → <code>/new</code>，发送：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run a Codex Security scan on this repository.</span></span></code></pre></div><p>等到结束。先看终端摘要，再读 <code>report.md</code>。任何配置改动都要先读完补丁再批。</p><h2 id="cli-和-sdk-包" tabindex="-1">CLI 和 SDK 包 <a class="header-anchor" href="#cli-和-sdk-包" aria-label="Permalink to &quot;CLI 和 SDK 包&quot;">​</a></h2><p>公开包：<a href="https://github.com/openai/codex-security" target="_blank" rel="noreferrer"><code>@openai/codex-security</code></a>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @openai/codex-security</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>同一套扫描器跨仓库、跨时间：发现 GitHub 仓库、恢复批量扫描、跟踪 findings、记录误报、设费用上限、进 CI。TypeScript SDK 把扫描、进度和取消嵌进工具。</p><table tabindex="0"><thead><tr><th>工作</th><th>官方页</th></tr></thead><tbody><tr><td>第一次终端扫描</td><td><a href="https://learn.chatgpt.com/docs/security/cli" target="_blank" rel="noreferrer">CLI quickstart</a></td></tr><tr><td>批量 / CSV 清单</td><td><a href="https://learn.chatgpt.com/docs/security/cli/bulk-scans" target="_blank" rel="noreferrer">Bulk scans</a></td></tr><tr><td>CI 里 PR / MR，SARIF</td><td><a href="https://learn.chatgpt.com/docs/security/cli/ci" target="_blank" rel="noreferrer">CLI in CI</a></td></tr><tr><td>flag 和退出码</td><td><a href="https://learn.chatgpt.com/docs/security/cli/reference" target="_blank" rel="noreferrer">CLI reference</a></td></tr><tr><td>从应用代码调用</td><td><a href="https://learn.chatgpt.com/docs/security/sdk" target="_blank" rel="noreferrer">TypeScript SDK</a></td></tr></tbody></table><p>这<strong>不是</strong>通用 <a href="https://learn.chatgpt.com/docs/codex-sdk" target="_blank" rel="noreferrer">Codex SDK</a>（<code>@openai/codex-sdk</code>）。结构化安全 findings 才用 Security SDK。</p><h2 id="cloud-研究预览" tabindex="-1">Cloud（研究预览） <a class="header-anchor" href="#cloud-研究预览" aria-label="Permalink to &quot;Cloud（研究预览）&quot;">​</a></h2><p>Codex Security cloud 按提交扫已连接的 GitHub 仓库。它建仓库专属威胁模型，在隔离环境里验证高信号问题，再给出带证据和补丁建议的排序结果。</p><p>仓库看不见时，先确认它在 Codex Cloud workspace 里可见，或联系 OpenAI 客户团队。</p><p>威胁模型：<a href="https://learn.chatgpt.com/docs/security/threat-model" target="_blank" rel="noreferrer">Improving the threat model</a>。PR 评审：<a href="https://learn.chatgpt.com/docs/security/security-review" target="_blank" rel="noreferrer">Security Review</a>。</p><h2 id="首扫之后" tabindex="-1">首扫之后 <a class="header-anchor" href="#首扫之后" aria-label="Permalink to &quot;首扫之后&quot;">​</a></h2><table tabindex="0"><thead><tr><th>下一步</th><th>官方页</th></tr></thead><tbody><tr><td>更深、更慢的扫描</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/deep-scans" target="_blank" rel="noreferrer">Deep scans</a></td></tr><tr><td>审 PR / 分支 / 补丁</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/code-changes" target="_blank" rel="noreferrer">Code changes</a></td></tr><tr><td>消化已有 backlog</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/triage-backlog" target="_blank" rel="noreferrer">Triage</a></td></tr><tr><td>有界修复并验证</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/fix-findings" target="_blank" rel="noreferrer">Fix findings</a></td></tr><tr><td>导出 / 跟踪</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/export-findings" target="_blank" rel="noreferrer">Export findings</a></td></tr></tbody></table><p>完成的扫描通常写出 <code>report.md</code>，可选 <code>findings/&lt;slug&gt;/</code> 和 <code>hardening/</code>，以及 <code>scan-manifest.json</code>、<code>findings.json</code>、<code>coverage.json</code>。目录要整份留着，<code>report.md</code> 里的链接才不断。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>结果</th><th>改做</th></tr></thead><tbody><tr><td>扫无权评估的仓库</td><td>政策和法律问题</td><td>停下。只评估已授权代码</td></tr><tr><td>把 finding 当铁证</td><td>仍有误报</td><td>读证据；Cloud/插件会验证，你仍要拍板</td></tr><tr><td>要一份能用的 exploit</td><td>本教程不做</td><td>看官方证据；这里不写 exploit PoC</td></tr><tr><td>Security SDK 和 Codex SDK 搞混</td><td>装错包</td><td><code>@openai/codex-security</code> vs <code>@openai/codex-sdk</code></td></tr><tr><td>跳过 Trusted Access</td><td>扫描变弱</td><td>符合条件就去 <a href="https://chatgpt.com/cyber" target="_blank" rel="noreferrer">chatgpt.com/cyber</a></td></tr></tbody></table><h2 id="实际用例" tabindex="-1">实际用例 <a class="header-anchor" href="#实际用例" aria-label="Permalink to &quot;实际用例&quot;">​</a></h2><p>发版前对 <code>packages/api</code> 做一次<strong>只读</strong>插件扫描。接受一条 finding，要有界补丁，再跑相关测试。PR diff 走 Security CLI。workspace 有研究预览就把 Cloud 开在 GitHub org 上。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>插件首扫 → <a href="https://learn.chatgpt.com/docs/security/plugin" target="_blank" rel="noreferrer">Plugin quickstart</a></li><li>可重复 CLI → <a href="https://learn.chatgpt.com/docs/security/cli" target="_blank" rel="noreferrer">CLI quickstart</a></li><li>托管 GitHub → <a href="https://learn.chatgpt.com/docs/security/setup" target="_blank" rel="noreferrer">Cloud setup</a></li><li>Agent 沙箱（另一层） → <a href="https://learn.chatgpt.com/docs/agent-approvals-security" target="_blank" rel="noreferrer">Agent approvals &amp; security</a></li></ol><h2 id="官方来源" tabindex="-1">官方来源 <a class="header-anchor" href="#官方来源" aria-label="Permalink to &quot;官方来源&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/security" target="_blank" rel="noreferrer">Codex Security（落地页）</a></li><li><a href="https://learn.chatgpt.com/docs/security" target="_blank" rel="noreferrer">Codex Security（文档）</a></li><li><a href="https://learn.chatgpt.com/docs/security/plugin" target="_blank" rel="noreferrer">Plugin quickstart</a> · <a href="https://learn.chatgpt.com/docs/security/plugin/workbench" target="_blank" rel="noreferrer">Workbench</a></li><li><a href="https://learn.chatgpt.com/docs/security/cli" target="_blank" rel="noreferrer">CLI</a> · <a href="https://learn.chatgpt.com/docs/security/sdk" target="_blank" rel="noreferrer">SDK</a></li><li><a href="https://learn.chatgpt.com/docs/security/setup" target="_blank" rel="noreferrer">Cloud setup</a> · <a href="https://learn.chatgpt.com/docs/security/faq" target="_blank" rel="noreferrer">Cloud FAQ</a></li><li><a href="https://learn.chatgpt.com/docs/security/security-review" target="_blank" rel="noreferrer">Security Review</a></li><li><a href="https://github.com/openai/codex-security" target="_blank" rel="noreferrer">openai/codex-security</a></li></ul>`,42)])])}const k=e(s,[["render",c]]);export{f as __pageData,k as default};
